declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/business_microsite_v1130.php';require_once __DIR__.'/app/business_crm_ui_v1180.php';$u=current_user();if(!$u){header('Location: /login.php?redirect='.rawurlencode($_SERVER['REQUEST_URI']??'/business-crm-v1180.php'));exit;}$uid=(int)$u['id'];$owned=sk1170_owner_businesses($uid);$bid=(int)($_REQUEST['business_id']??0);if($bid<1&&$owned)$bid=(int)$owned[0]['id'];$b=$bid?sk1130_business($bid):[];if(!$b||!sk1170_can_manage($b,$u)){http_response_code(403);exit('You do not manage this business.');}$msg='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=(string)($_POST['action']??'');if($a==='reply'){sk1180_message_add((int)$_POST['conversation_id'],'owner',(string)$_POST['message'],$uid);$msg='Reply sent.';}elseif($a==='quote'){sk1180_quote_create($bid,(int)$_POST['contact_id'],(int)($_POST['conversation_id']??0),$_POST,$uid);$msg='Quotation sent.';}elseif($a==='followup'){sk1180_followup_create($bid,(int)$_POST['contact_id'],(string)$_POST['due_at'],(string)$_POST['note'],$uid);$msg='Follow-up added.';}elseif($a==='followup_done'){sk1180_followup_done((int)$_POST['followup_id'],$bid);$msg='Follow-up completed.';}}}catch(Throwable $e){$err=$e->getMessage();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business CRM</title></head><body><?php if($msg):?><div style="padding:12px;background:#eafaf0"><?=sk1130_h($msg)?></div><?php endif;?><?php if($err):?><div style="padding:12px;background:#fff0f0"><?=sk1130_h($err)?></div><?php endif;?><?php sk1180_render_crm_page($b,$u,false);?></body></html>